if version.l10n_vn_pit_method == 'flat_non_resident':
    result = categories['VN_OVERTIME']
elif payslip._rule_parameter('l10n_vn_pit_overtime_exemption') == 'full':
    result = 0
else:
    # Only the premium above the wage of the normal working hours is exempt
    result = min(categories['VN_OVERTIME'], payslip._l10n_vn_get_worked_days_amount(overtime=True))

if version.l10n_vn_pit_method == 'flat_non_resident' or not payslip._rule_parameter('l10n_vn_pit_unused_leave_payout_exempt'):
    result = result_rules['UNUSED_LEAVE_PAYOUT']['total']
else:
    result = 0

taxable_income = result_rules['TAXABLE_INCOME']['total']
if version.l10n_vn_pit_method == 'progressive':
    result = max(taxable_income + categories['VN_INSURANCE_EMP'] - categories['VN_PIT_DEDUCTION'], 0)
else:
    result = taxable_income

taxable_income = result_rules['TAXABLE_INCOME']['total']
if version.l10n_vn_pit_method == 'flat_non_resident':
    result = -taxable_income * payslip._rule_parameter('l10n_vn_pit_non_resident_rate') / 100
elif version.l10n_vn_pit_method == 'flat_casual':
    if taxable_income >= payslip._rule_parameter('l10n_vn_pit_casual_threshold'):
        result = -taxable_income * payslip._rule_parameter('l10n_vn_pit_casual_rate') / 100
    else:
        result = 0
else:
    result = -payslip._l10n_vn_compute_progressive_tax(result_rules['ASSESSABLE_INCOME']['total'])
